1、三次指数平滑算法MATLAB程序
clc,clear
load fulua.txt
yt=fulua;
n=length(yt);
yt=fulua;
n=size(yt,1)
alpha=0.4;
stl_0=mean(yt(1:3));
st2_0=stl_0,st3_0=st1_0,
st1(1)=alpha*yt（1)+(1-alpha)*st1_0;
st2（1)=alpha*stl(1)+(1-alpha)*st2_0;
st3(1)=alpha*st2(1)+(1-alpha)*st3_0;
fori=2:n
st1(i)=alpha*yt(i)+(1-alpha)*st1(i-1),
st2(i)=alpha*stl(i)+(1-alpha)*st2(i-1);
st3(i)=alpha*st2(i)+(1-alpha)*st3(i-1);
end
xlswrite(fulua',[stl',st2',st3'])
stl=[stl_0,st1];
st2=[st2_0,st2]
st3=[st3_0,st3]
a=3*st1-3*st2+st3;
b=0.5*alpha/(1-alpha)2*(6-5*alpha)*st1-2*(5-4*alpha)*st2+(4-3*alpha)*st3)
c=0.5*alpha^2/(1-alpha)^2*（st1-2*st2+st3)
yu=a+b+c;
fori=1:n+1
ifyu(i)<0
yu(i)=0,
end
end
xlswrite(fulua.xls,1,sheetl',D1)
plot(1:n,yt,r,1:n,yu(1:n)b)
title（物料编码6004020900）
legend（实际值，预测值）；
kn=1
result=[a(n+1)b(n+1)c(n+1);
中国大学生在线
for i=1:kn yshu(i)=polyval(result,i),
str=char（[Bint2str(n+i）]x.
